export class ProceduralMemory {
  constructor() {
    this.memoryStore = [];
  }

  addWorkflow(workflow, metadata) {
    this.memoryStore.push({ workflow, metadata });
  }

  refineWorkflows(performanceMetrics) {
    this.memoryStore = this.memoryStore.map(entry => {
      const refinedWorkflow = this.adaptiveRefinement(entry.workflow, performanceMetrics);
      return { ...entry, workflow: refinedWorkflow };
    });
  }

  adaptiveRefinement(workflow, metrics) {
    // Example refinement logic based on performance metrics
    return workflow.map(step => ({ ...step, confidence: step.confidence * metrics.adjustmentFactor }));
  }

  getBestWorkflows() {
    return this.memoryStore.sort((a, b) => b.metadata.confidence - a.metadata.confidence);
  }
}